func TestLoadWingmanStateDirect(t *testing.T) {
	t.Parallel()

	tmpDir := t.TempDir()
	entireDir := filepath.Join(tmpDir, ".entire")
	if err := os.MkdirAll(entireDir, 0o755); err != nil {
		t.Fatalf("failed to create .entire: %v", err)
	}

	// No state file — returns nil
	if state := loadWingmanStateDirect(tmpDir); state != nil {
		t.Error("expected nil for missing state file")
	}

	// Write a state file
	now := time.Now()
	stateJSON := `{"session_id":"sess-1","files_hash":"hash1","reviewed_at":"` + now.Format(time.RFC3339Nano) + `","review_applied":false}`
	if err := os.WriteFile(filepath.Join(entireDir, "wingman-state.json"), []byte(stateJSON), 0o644); err != nil {
		t.Fatalf("failed to write state: %v", err)
	}

	state := loadWingmanStateDirect(tmpDir)
	if state == nil {
		t.Fatal("expected non-nil state")
	}
	if state.SessionID != "sess-1" {
		t.Errorf("SessionID: got %q, want %q", state.SessionID, "sess-1")
	}
}

